import sys
from collections import deque

def main():
    # Read all tokens from standard input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    C = input_data[1:]

    # in_edges[u] = list of (a, k) where a -> u has label k (0-25)
    in_edges = [[] for _ in range(N)]
    # out_edges_by_char[v][k] = list of b where v -> b has label k
    out_edges_by_char = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            ch = C[i][j]
            if ch != "-":
                k = ord(ch) - ord('a')
                in_edges[j].append((i, k))
                out_edges_by_char[i][k].append(j)

    # dist1 tracks shortest valid palindrome paths between (u, v)
    dist1 = [[-1] * N for _ in range(N)]

    # dist2 tracks intermediate paths between (a, v) waiting for an outgoing character 'k' from v
    dist2 = [[[-1] * 26 for _ in range(N)] for _ in range(N)]

    q = deque()

    # Base case 1: Empty paths (Length 0)
    for i in range(N):
        dist1[i][i] = 0
        q.append((1, i, i))

    # Base case 2: Single edge paths (Length 1)
    for i in range(N):
        for j in range(N):
            if C[i][j] != "-" and i != j:
                dist1[i][j] = 1
                q.append((1, i, j))

    while q:
        item = q.popleft()

        if item[0] == 1:
            _, u, v = item
            d = dist1[u][v]

            # Left expansion: prepend character `k`
            for a, k in in_edges[u]:
                if dist2[a][v][k] == -1:
                    dist2[a][v][k] = d + 1
                    q.append((2, a, v, k))

        else:
            _, a, v, k = item
            d = dist2[a][v][k]

            # Right expansion: append the expected character `k` to balance the palindrome
            for b in out_edges_by_char[v][k]:
                if dist1[a][b] == -1:
                    dist1[a][b] = d + 1
                    q.append((1, a, b))

    # Format output
    out = []
    for i in range(N):
        out.append(" ".join(str(dist1[i][j]) for j in range(N)))
    print("\n".join(out))

if __name__ == "__main__":
    main()
